"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 step 2: retrain only the last read-out of our main model (L1), so that its decisions follow what it hears
(docs/iterations.md, 2026-11-19; approved by the author). Exploratory, local, no API; dev for evaluation; test untouched.

Design, fixed in the log before running:
- The model is unchanged: frozen VoxTurn plus our LoRA (p1v4), one forward pass as scored on dev (phrasing 0). Only
  the read-out that turns the last-layer states into a decision is replaced.
- New read-out: per question (S, R), a logistic regression on the last-layer states at the question's two option
  positions, concatenated (2,048 numbers; the old head reads the same states with one shared 1,024 weight vector).
  Setting "ears": the same plus the mean and max of the 104 audio tokens (as in the probe pilot). The setting is
  chosen on dev by the plan's rule (floors, five-part mean, lowest floor), as for every system.
- Training data: every train window, one input each (seed 0). The ring and knock labels the model can check by
  listening (phone, doorbell or knock detections overlapping the 8 s window it hears) are made independent of the
  truth, as in the probe pilot. With probability 0.5 a point is changed: if its window holds a real phone, doorbell or
  knock clip, those detections are removed; otherwise one false label is added (phone, doorbell or knock at random,
  confidence U(0.3, 1.0), placed as in the injection pilot). In the unchanged half, true labels in the window get one
  confidence from U(0.3, 1.0), so that a confidence near 1 does not mark a true label; natural false alarms stay.
  Labels outside the window (episode history) are not touched. Gold answers are unchanged.
- Fit: standardised features; weight decay chosen from {1e-4, 1e-3, 1e-2, 1e-1} by log loss on a 20% holdout of
  train grouped by unit, then refitted on all of train (AdamW, lr 1e-3, batch 2,048, 8 epochs).
- Dev inputs: natural (as scored); false labels at 0.9 (the injection pilot's false phone label at every no-event
  point, with its confidence set to 0.9); true labels removed (phone, doorbell and knock detections overlapping the
  window removed). Thresholds by the plan's operating-point rule on natural dev, kept fixed for the other inputs.
- Criteria, fixed now:
  1. hard subset (ring or knock labels of confidence 0.5-0.9 at R-hear points; 24 real, 51 false): real labels
     followed at least 18 times and false labels at most 5 times;
  2. five-part mean on natural dev at least 0.934 (ours 0.944 minus 1 point);
  3. with false labels at 0.9, the five-part mean drops by at most 2 points.
  Also reported: parts, floors and the audio-decisive part; the same three inputs for the current main model (its
  own head on the same states); the hearing-decision gap on the hard subset (decision AUC vs the probe pilot's
  AUCs); intervals against ours, L3, the combination and each Gemini reader's current dev choice.
usage (repo root):
  .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_readout.py extract train
  .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_readout.py extract dev
  .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_readout.py fit
  .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_readout.py eval
Outputs: data/p1v4/runs/readout/ (features, read-outs), results/main_v04/readout_dev.json.
"""
import json
import os
import random
import sys
import time

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_score as S  # noqa: E402

R = "data/p1v4/runs"
OUT = f"{R}/readout"
EVENT = ("phone", "doorbell", "knock")
WDS = (1e-4, 1e-3, 1e-2, 1e-1)
SEED = 0
TASK = {"S": "stop", "R": "respond"}


def keyed(d):
    return {(k.split("|")[0], k.split("|")[1], int(k.split("|")[2])): v for k, v in d.items()}


def in_window(s, t):
    return s[0] in EVENT and s[2] > t - D.WIN_S and s[1] < t


def is_real(r, t):
    return any(c in EVENT for c, _, _ in D.window_events(r, t))


def false_span(r, p, rng):
    """As the injection pilot: ends 0.3-1.5 s before the line (or the point), 1.5-3.0 s long, inside the window."""
    src = {s["id"]: s for s in r["sources"]}
    t = p["t"]
    ls = src[p["line"]]["start"] if p.get("line") else t
    s1 = ls - rng.uniform(0.3, 1.5)
    s0 = max(s1 - rng.uniform(1.5, 3.0), t - D.WIN_S + 0.01)
    return (round(s0, 2), round(s1, 2)) if s1 - s0 >= 0.5 else None


class Edited(C.Context):
    """Sound lists edited per point: {pid: ("drop", t) | ("conf", t, c) | ("add", cls, s0, s1, c)}; "drop" and
    "conf" act on phone/doorbell/knock detections overlapping the window [t - 8, t]."""

    def __init__(self, which, edits):
        super().__init__(which)
        self.edits = edits

    def point(self, r, k):
        tr, sc, tags, snd = super().point(r, k)
        e = self.edits.get(self.pid(r, k))
        if e:
            if e[0] == "drop":
                snd = [s for s in snd if not in_window(s, e[1])]
            elif e[0] == "conf":
                snd = [(s[0], s[1], s[2], e[2]) if in_window(s, e[1]) else s for s in snd]
            elif e[0] == "add":
                snd = sorted(list(snd) + [tuple(e[1:])], key=lambda s: (s[1], s[0]))
        return tr, sc, tags, snd


def train_edits(rows):
    rng = random.Random(SEED)
    edits, cond = {}, {}
    for r in rows:
        for p in r["points"]:
            pid = f"{r['unit']}|{r['version']}|{p['k']}"
            real = is_real(r, p["t"])
            if rng.random() < 0.5:
                if real:
                    edits[pid], cond[pid] = ("drop", p["t"]), "real, labels removed"
                else:
                    span = false_span(r, p, rng)
                    if span:
                        edits[pid] = ("add", rng.choice(EVENT), span[0], span[1], round(rng.uniform(0.3, 1.0), 3))
                        cond[pid] = "no event, false label"
                    else:
                        cond[pid] = "no event, natural (no room)"
            else:
                if real:
                    edits[pid], cond[pid] = ("conf", p["t"], round(rng.uniform(0.3, 1.0), 3)), "real, labels kept"
                else:
                    cond[pid] = "no event, natural"
    return edits, cond


def dev_edits(rows, which):
    if which == "natural":
        return {}
    if which == "removed":
        return {f"{r['unit']}|{r['version']}|{p['k']}": ("drop", p["t"]) for r in rows for p in r["points"]}
    inj = json.load(open(f"{R}/inject_pilot/injections.json"))
    return {pid: ("add", e[0], e[1], e[2], 0.9) for pid, e in inj.items()}


# ------------------------------------------------------------------------------------------------ extraction

def forward_states(model, waves, texts, markers, qlists):
    """As L1v4.forward: last-layer states at each question's two option positions (Q, 2048), the pooled audio tokens
    (B, 2048), the question's window index (Q) and the old head's P(yes) (Q)."""
    import torch
    import torch.nn as nn
    import torch.nn.functional as F
    import p1v4_l1 as L1
    vt, mod = model.vt, model.mod
    dev = vt.head.weight.device
    emb = vt.llm.get_input_embeddings()
    with torch.no_grad(), torch.autocast("cuda", dtype=torch.bfloat16):
        audio = vt.encode_audio(vt.mel(waves))
        seqs, opt_pos, blocks = [], [], []
        for b in range(len(texts)):
            ids = vt.context_ids(texts[b], markers[b], "en", L1.MAX_TEXT_TOKENS)
            prefix = torch.cat([emb(torch.tensor(vt.seq_head + vt.audio_open, device=dev)), audio[b],
                                emb(torch.tensor(vt.audio_close + ids, device=dev))], 0)
            parts, start, spans = [prefix], len(prefix), []
            for task in qlists[b]:
                q_ids, q_pos = vt.prompt(task, "en", 0)
                parts.append(emb(torch.tensor(q_ids, device=dev)))
                opt_pos.append([start + p for p in q_pos])
                spans.append((start, len(q_ids)))
                start += len(q_ids)
            seqs.append(torch.cat(parts, 0))
            blocks.append(spans)
        x = nn.utils.rnn.pad_sequence(seqs, batch_first=True)
        x = F.pad(x, (0, 0, 0, -x.shape[1] % mod.LEN_BUCKET))
        if any(len(s) > 1 for s in blocks):
            kw = vt.isolating_mask(blocks, x.shape[1], dev)
            hid = vt.llm(inputs_embeds=x, attention_mask=kw["attention_mask"],
                         position_ids=kw["position_ids"]).last_hidden_state
        else:
            hid = vt.llm(inputs_embeds=x).last_hidden_state
        q_seq = torch.tensor([i for i, spans in enumerate(blocks) for _ in spans], device=dev)
        pos = torch.tensor(opt_pos, device=dev)
        h = hid[q_seq[:, None], pos].float()
    with torch.no_grad():
        p_old = model.new_head(h).squeeze(-1).softmax(-1)[:, 1]
    a = audio.float()
    ears = torch.cat([a.mean(1), a.amax(1)], -1)
    return (h.reshape(h.shape[0], -1).cpu().numpy(), ears.cpu().numpy(), q_seq.cpu().numpy(),
            p_old.cpu().numpy())


def extract(which):
    import soundfile as sf
    import torch
    import p1v4_l1 as L1
    D.gpu_guard()
    os.makedirs(OUT, exist_ok=True)
    rows = D.load_rows(which)
    wins = D.windows_of(rows, which)
    rows_by = {(r["unit"], r["version"]): r for r in rows}
    conds = ["train"] if which == "train" else ["natural", "false09", "removed"]
    model = L1.build()
    L1.load_new_state(model, torch.load(f"{R}/l1/l1_new.pt", weights_only=True))
    model.eval()
    for cond in conds:
        if cond == "train":
            edits, labels = train_edits(rows)
        else:
            edits = dev_edits(rows, cond)
            labels = {pid: "edited" for pid in edits}
        ctx = Edited(which, edits)
        items = []
        for w in wins:
            r = rows_by[w["key"]]
            text, asks = ctx.situation(r, w["k"], "full")
            qs = [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]
            snd = [s for s in ctx.point(r, w["k"])[3] if in_window(s, w["t"])]
            items.append({"id": w["id"], "unit": w["unit"], "part": w["part"], "path": w["path"], "text": text,
                          "marker": "agent" if w["assistant_speaking"] else "user", "qs": qs,
                          "gold": [-1 if w["gold"].get(q) is None else
                                   int(w["gold"][q] == ("stop" if q == "S" else "respond")) for q in qs],
                          "real": is_real(r, w["t"]), "conf": max([s[3] for s in snd], default=-1.0)})
        H, E, QW, QT, QG, PO = [], [], [], [], [], []
        t0 = time.time()
        B = 8
        for i in range(0, len(items), B):
            chunk = items[i:i + B]
            waves = torch.stack([torch.from_numpy(sf.read(it["path"], dtype="float32")[0]) for it in chunk]).cuda()
            h, e, qs, po = forward_states(model, waves, [it["text"] for it in chunk], [it["marker"] for it in chunk],
                                          [[TASK[q] for q in it["qs"]] for it in chunk])
            H.append(h.astype(np.float16))
            E.append(e.astype(np.float16))
            QW.append(qs + i)
            QT += [q for it in chunk for q in it["qs"]]
            QG += [g for it in chunk for g in it["gold"]]
            PO.append(po)
            if (i // B) % 500 == 0:
                print(f"{which}/{cond}: {i + len(chunk)}/{len(items)} windows {time.time() - t0:.0f} s", flush=True)
        np.savez(f"{OUT}/feats_{which}_{cond}.npz", states=np.concatenate(H), ears=np.concatenate(E),
                 q_win=np.concatenate(QW), q_task=np.array(QT), q_gold=np.array(QG), p_old=np.concatenate(PO),
                 ids=np.array([it["id"] for it in items]), units=np.array([it["unit"] for it in items]),
                 parts=np.array([it["part"] for it in items]), real=np.array([it["real"] for it in items]),
                 conf=np.array([it["conf"] for it in items]),
                 cond=np.array([labels.get(it["id"], "unedited") for it in items]))
        print(f"{which}/{cond} done: {len(items)} windows, {len(QT)} questions, {time.time() - t0:.0f} s", flush=True)
        if cond == "natural":
            stored = keyed(json.load(open(f"{R}/l1/scores_dev.json")))
            qw, po = np.concatenate(QW), np.concatenate(PO)
            diff = [abs(stored[tuple(items[w]["id"].split("|")[:2]) + (int(items[w]["id"].split("|")[2]),)][q] - p)
                    for w, q, p in zip(qw, QT, po)]
            print(f"check vs stored L1 dev scores: max |diff| {max(diff):.5f}, median {np.median(diff):.6f}",
                  flush=True)


# ------------------------------------------------------------------------------------------------ read-outs

def design(z, setting):
    X = z["states"]
    if setting == "ears":
        X = np.concatenate([X, z["ears"][z["q_win"]]], 1)
    return X


def train_logreg(X, y, wd, epochs=8, seed=0):
    import torch
    g = torch.Generator().manual_seed(seed)
    dev = "cuda"
    Xt = torch.from_numpy(X).to(dev)
    yt = torch.from_numpy(y.astype(np.float32)).to(dev)
    lin = torch.nn.Linear(X.shape[1], 1).to(dev)
    opt = torch.optim.AdamW(lin.parameters(), lr=1e-3, weight_decay=wd)
    for _ in range(epochs):
        perm = torch.randperm(len(y), generator=g).to(dev)
        for j in range(0, len(y), 2048):
            b = perm[j:j + 2048]
            loss = torch.nn.functional.binary_cross_entropy_with_logits(lin(Xt[b].float()).squeeze(-1), yt[b])
            opt.zero_grad()
            loss.backward()
            opt.step()
    return lin


def predict(lin, X):
    import torch
    with torch.no_grad():
        out = []
        for j in range(0, len(X), 8192):
            out.append(torch.sigmoid(lin(torch.from_numpy(X[j:j + 8192]).cuda().float()).squeeze(-1)).cpu().numpy())
    return np.concatenate(out)


def fit():
    import torch
    D.gpu_guard()
    z = dict(np.load(f"{OUT}/feats_train_train.npz"))
    units = z["units"][z["q_win"]]
    rng = np.random.default_rng(SEED)
    uniq = np.unique(z["units"])
    hold_units = set(rng.choice(uniq, size=len(uniq) // 5, replace=False))
    hold = np.array([u in hold_units for u in units])
    log, models = {}, {}
    for setting in ("states", "ears"):
        X = design(z, setting).astype(np.float32)
        for q in ("S", "R"):
            m = (z["q_task"] == q) & (z["q_gold"] >= 0)
            mu, sd = X[m].mean(0), X[m].std(0) + 1e-6
            Xs = ((X - mu) / sd).astype(np.float32)
            y = z["q_gold"]
            best = None
            for wd in WDS:
                lin = train_logreg(Xs[m & ~hold], y[m & ~hold], wd)
                p = np.clip(predict(lin, Xs[m & hold]), 1e-7, 1 - 1e-7)
                yy = y[m & hold]
                ll = float(-np.mean(yy * np.log(p) + (1 - yy) * np.log(1 - p)))
                log[f"{setting} {q} wd {wd}"] = ll
                print(f"{setting} {q} wd {wd}: holdout log loss {ll:.4f} (n {int((m & hold).sum())})", flush=True)
                if best is None or ll < best[0]:
                    best = (ll, wd)
            lin = train_logreg(Xs[m], y[m], best[1])
            models[f"{setting}|{q}"] = {"mu": mu, "sd": sd, "w": lin.weight.detach().cpu().numpy()[0],
                                        "b": float(lin.bias.detach().cpu().numpy()[0]), "wd": best[1]}
            print(f"{setting} {q}: chosen wd {best[1]}, refitted on {int(m.sum())} questions", flush=True)
    np.savez(f"{OUT}/readouts.npz", **{f"{k}|{f}": v for k, d in models.items() for f, v in d.items()})
    json.dump(log, open(f"{OUT}/fit_log.json", "w"), indent=1)


def load_readouts():
    z = np.load(f"{OUT}/readouts.npz")
    out = {}
    for k in z.files:
        s, q, f = k.split("|")
        out.setdefault((s, q), {})[f] = z[k]
    return out


def scores_of(z, setting, ro):
    """{(unit, version, k): {"S": p, "R": p}} from the new read-out, or the old head when setting is None."""
    sc = {}
    X = None if setting is None else design(z, setting).astype(np.float32)
    p = np.zeros(len(z["q_task"]))
    for q in ("S", "R"):
        m = z["q_task"] == q
        if setting is None:
            p[m] = z["p_old"][m]
        else:
            r = ro[(setting, q)]
            lg = ((X[m] - r["mu"]) / r["sd"]) @ r["w"] + float(r["b"])
            p[m] = 1 / (1 + np.exp(-lg))
    for w, q, x in zip(z["q_win"], z["q_task"], p):
        i = z["ids"][w].split("|")
        sc.setdefault((i[0], i[1], int(i[2])), {})[str(q)] = float(x)
    return sc


def eval_():
    import p1v4_combo_pilot as CP
    import p1v4_trust_curves as TC
    from sklearn.metrics import roc_auc_score
    rows = D.load_rows("dev")
    groups = S.load_groups("dev")
    pts = TC.r_hear_points(rows, C.Context("dev"))
    hard = {q["key"]: q["real"] for q in pts if q["conf"] is not None and 0.5 <= q["conf"] < 0.9}
    ro = load_readouts()
    dev = {c: dict(np.load(f"{OUT}/feats_dev_{c}.npz")) for c in ("natural", "false09", "removed")}
    rep = json.load(open("results/main_v04/dev_report.json"))["systems"]
    res = {"settings": {}, "criteria": {}}
    systems = {}
    for setting in ("states", "ears", None):
        name = "old head" if setting is None else setting
        sc = {c: scores_of(dev[c], setting, ro) for c in dev}
        if setting is None:
            op = rep["L1"]["operating_point"]
            th = (op["th_s"], op["th_r"])
        else:
            op = S.operating_point(rows, sc["natural"])
            th = (op["th_s"], op["th_r"])
        out = {"th_s": th[0], "th_r": th[1]}
        for c in dev:
            dec = S.decide(sc[c], *th)
            T = S.unit_table(rows, dec, groups)
            m = S.metrics(T)
            out[c] = {"primary": m["primary"], "parts": m["parts"], "audio": m["audio"],
                      "floors": m["floors"], "mid_confidence_follow": CP.mid_follow(pts, dec)}
            if c == "natural":
                systems[name] = T
                keys = list(hard)
                y = np.array([hard[k] for k in keys])
                s_ = np.array([1 - sc[c][k]["R"] for k in keys])
                out["hard_subset_decision_auc"] = float(roc_auc_score(y, s_))
        out["drop_false09"] = out["natural"]["primary"] - out["false09"]["primary"]
        out["drop_removed"] = out["natural"]["primary"] - out["removed"]["primary"]
        if setting is not None:
            out["floors_met"] = op["floors_met"]
            out["lowest_floor"] = op["lowest_floor"]
        res["settings"][name] = out
    rank = {s: (res["settings"][s]["floors_met"], res["settings"][s]["natural"]["primary"],
                res["settings"][s]["lowest_floor"]) for s in ("states", "ears")}
    chosen = max(rank, key=rank.get)
    res["chosen"] = chosen
    c = res["settings"][chosen]
    mf = c["natural"]["mid_confidence_follow"]
    res["criteria"] = {"1 hard subset (real >= 18/24, false <= 5/51)": mf["real"][0] >= 18 and mf["false"][0] <= 5,
                       "2 five-part mean >= 0.934": c["natural"]["primary"] >= 0.934,
                       "3 drop under false labels at 0.9 <= 2 points": c["drop_false09"] <= 0.02}
    probe = json.load(open("results/main_v04/probe_pilot_dev.json"))["dev"]["natural"]["primary: label 0.5-0.9"]
    res["hearing_decision_gap"] = {"probe ears": probe["ears"], "probe last layer": probe["layer 28"],
                                   "old head decision": res["settings"]["old head"]["hard_subset_decision_auc"],
                                   "new read-out decision": c["hard_subset_decision_auc"]}
    l3 = keyed(json.load(open(f"{R}/l3/scores_dev.json")))
    op = rep["L3"]["operating_point"]
    others = {"ours (old head)": systems["old head"],
              "L3": S.unit_table(rows, S.decide(l3, op["th_s"], op["th_r"]), groups)}
    l1 = keyed(json.load(open(f"{R}/l1/scores_dev.json")))
    sc, _ = CP.combine(l1, l3, "logit", 0.5)
    op = S.operating_point(rows, sc)
    others["combination"] = S.unit_table(rows, S.decide(sc, op["th_s"], op["th_r"]), groups)
    for n, sd in (("B2-fast", "b2fast"), ("B2-strong", "b2strong")):
        op = rep[n]["operating_point"]
        sc = keyed(json.load(open(f"{R}/api/{sd}/scores_dev_{op['setting']}.json")))
        others[f"{n} ({op['setting']})"] = S.unit_table(rows, S.decide(sc, op["th_s"], op["th_r"]), groups)
    res["vs"] = {n: {w: S.interval(systems[chosen], T, w) for w in ("primary", "audio", "part:r_hear")}
                 for n, T in others.items()}
    json.dump(res, open("results/main_v04/readout_dev.json", "w"), indent=1)
    for s, x in res["settings"].items():
        n = x["natural"]
        print(f"{s:9s} natural {n['primary']:.3f} audio {n['audio']:.3f} parts "
              + " ".join(f"{p}:{n['parts'][p]:.3f}" for p in S.PARTS)
              + f" | mid follow real {n['mid_confidence_follow']['real'][0]}/24 false "
                f"{n['mid_confidence_follow']['false'][0]}/51 | hard AUC {x['hard_subset_decision_auc']:.3f}"
              + f" | false@0.9 {x['false09']['primary']:.3f} (drop {x['drop_false09']:+.3f})"
              + f" | removed {x['removed']['primary']:.3f} (drop {x['drop_removed']:+.3f})")
    print("chosen:", chosen, "| criteria:", json.dumps(res["criteria"]))
    print("hearing-decision gap:", json.dumps(res["hearing_decision_gap"]))
    for n, v in res["vs"].items():
        print(f"new - {n}: " + "; ".join(f"{w} {v[w]['point']:+.3f} [{v[w]['ci95'][0]:+.3f}, {v[w]['ci95'][1]:+.3f}]"
                                         for w in ("primary", "audio", "part:r_hear")))


if __name__ == "__main__":
    if sys.argv[1] == "extract":
        extract(sys.argv[2])
    elif sys.argv[1] == "fit":
        fit()
    elif sys.argv[1] == "eval":
        eval_()
    else:
        raise SystemExit(__doc__)
